00045     public static function getMenuPhp()
00046     {
00047         global $bearsamppBins, $bearsamppLang;
00048         $resultItems = $resultActions = '';
00049 
00050         $isEnabled = $bearsamppBins->getPhp()->isEnable();
00051 
00052         // Download
00053         $resultItems .= TplAestan::getItemLink($bearsamppLang->getValue(Lang::DOWNLOAD_MORE),
00054             HttpClient::getWebsiteUrl('module/php', '#releases'),
00055             false,
00056             TplAestan::GLYPH_BROWSER
00057         ) . PHP_EOL;
00058 
00059         // Enable
00060         $tplEnable = TplApp::getActionMulti(
00061             self::ACTION_ENABLE, array($isEnabled ? Config::DISABLED : Config::ENABLED),
00062             array($bearsamppLang->getValue(Lang::MENU_ENABLE), $isEnabled ? TplAestan::GLYPH_CHECK : ''),
00063             false, get_called_class()
00064         );
00065         $resultItems .= $tplEnable[TplApp::SECTION_CALL] . PHP_EOL;
00066         $resultActions .= $tplEnable[TplApp::SECTION_CONTENT] . PHP_EOL;
00067 
00068         if ($isEnabled) {
00069             $resultItems .= TplAestan::getItemSeparator() . PHP_EOL;
00070 
00071             // Versions
00072             $tplVersions = TplApp::getMenu($bearsamppLang->getValue(Lang::VERSIONS), self::MENU_VERSIONS, get_called_class());
00073             $resultItems .= $tplVersions[TplApp::SECTION_CALL] . PHP_EOL;
00074             $resultActions .= $tplVersions[TplApp::SECTION_CONTENT] . PHP_EOL;
00075 
00076             // Settings
00077             $tplSettings = TplApp::getMenu($bearsamppLang->getValue(Lang::SETTINGS), self::MENU_SETTINGS, get_called_class());
00078             $resultItems .= $tplSettings[TplApp::SECTION_CALL] . PHP_EOL;
00079             $resultActions .= $tplSettings[TplApp::SECTION_CONTENT] . PHP_EOL;
00080 
00081             // Extensions
00082             $tplExtensions = TplApp::getMenu($bearsamppLang->getValue(Lang::EXTENSIONS), self::MENU_EXTENSIONS, get_called_class());
00083             $resultItems .= $tplExtensions[TplApp::SECTION_CALL] . PHP_EOL;
00084             $resultActions .= $tplExtensions[TplApp::SECTION_CONTENT];
00085 
00086             // Conf
00087             $resultItems .= TplAestan::getItemNotepad(basename($bearsamppBins->getPhp()->getConf()), $bearsamppBins->getPhp()->getConf()) . PHP_EOL;
00088 
00089             // Errors log
00090             $resultItems .= TplAestan::getItemNotepad($bearsamppLang->getValue(Lang::MENU_ERROR_LOGS), $bearsamppBins->getPhp()->getErrorLog()) . PHP_EOL;
00091         }
00092 
00093         return $resultItems . PHP_EOL . $resultActions;
00094     }
