00103     public static function getMenuPhpVersions()
00104     {
00105         global $bearsamppBins;
00106         $items = '';
00107         $actions = '';
00108 
00109         foreach ($bearsamppBins->getPhp()->getVersionList() as $version) {
00110             $glyph = '';
00111             $apachePhpModule = $bearsamppBins->getPhp()->getApacheModule($bearsamppBins->getApache()->getVersion(), $version);
00112             if ($apachePhpModule === false) {
00113                 $glyph = TplAestan::GLYPH_WARNING;
00114             } elseif ($version == $bearsamppBins->getPhp()->getVersion()) {
00115                 $glyph = TplAestan::GLYPH_CHECK;
00116             }
00117 
00118             $tplSwitchPhpVersion = TplApp::getActionMulti(
00119                 self::ACTION_SWITCH_VERSION, array($version),
00120                 array($version, $glyph),
00121                 false, get_called_class()
00122             );
00123 
00124             // Item
00125             $items .= $tplSwitchPhpVersion[TplApp::SECTION_CALL] . PHP_EOL;
00126 
00127             // Action
00128             $actions .= PHP_EOL . $tplSwitchPhpVersion[TplApp::SECTION_CONTENT];
00129         }
00130 
00131         return $items . $actions;
00132     }
