00175     public static function getMenuPhpSettings()
00176     {
00177         global $bearsamppBins;
00178 
00179         $menuItems = '';
00180         $menuActions = '';
00181         foreach ($bearsamppBins->getPhp()->getSettings() as $key => $value) {
00182             if (is_array($value)) {
00183                 $menuItems .= 'Type: submenu; ' .
00184                     'Caption: "' . $key . '"; ' .
00185                     'SubMenu: MenuPhpSetting-' . md5($key) . '; ' .
00186                     'Glyph: ' . TplAestan::GLYPH_FOLDER_CLOSE . PHP_EOL;
00187             } else {
00188                 $glyph = '';
00189                 $settingEnabled = $bearsamppBins->getPhp()->isSettingActive($value);
00190                 if (!$bearsamppBins->getPhp()->isSettingExists($value)) {
00191                     $glyph = TplAestan::GLYPH_WARNING;
00192                 } elseif ($settingEnabled) {
00193                     $glyph = TplAestan::GLYPH_CHECK;
00194                 }
00195                 $tplSwitchPhpSetting = TplApp::getActionMulti(
00196                     self::ACTION_SWITCH_SETTING, array($value, $settingEnabled),
00197                     array($key, $glyph),
00198                     false, get_called_class()
00199                 );
00200 
00201                 $menuItems .= $tplSwitchPhpSetting[TplApp::SECTION_CALL] . PHP_EOL;
00202                 $menuActions .= $tplSwitchPhpSetting[TplApp::SECTION_CONTENT];
00203             }
00204         }
00205 
00206         $submenusItems = '';
00207         $submenusActions = '';
00208         $submenuKeys = self::getSubmenuPhpSettings();
00209         foreach ($submenuKeys as $submenuKey) {
00210             $submenusItems .= PHP_EOL . '[MenuPhpSetting-' . md5($submenuKey) . ']' .
00211                 PHP_EOL . self::getSubmenuPhpSettings($submenuKey);
00212 
00213             $submenusActions .= self::getSubmenuPhpSettings($submenuKey, array(), array(), false);
00214         }
00215 
00216         return $menuItems . $submenusItems . PHP_EOL . $menuActions . $submenusActions;
00217     }
00218 
00231     private static function getSubmenuPhpSettings($passThr = array(), $result = array(), $settings = array(), $sectionCall = true)
00232     {
00233         global $bearsamppBins;
00234         $settings = empty($settings) ? $bearsamppBins->getPhp()->getSettings() : $settings;
00235 
00236         foreach ($settings as $key => $value) {
00237             if (is_array($value)) {
00238                 if (is_array($passThr)) {
00239                     array_push($result, $key);
00240                     $result = self::getSubmenuPhpSettings($passThr, $result, $value);
00241                 } else {
00242                     $result = is_array($result) ? '' : $result;
00243                     if ($key == $passThr) {
00244                         foreach ($value as $key2 => $value2) {
00245                             if (is_array($value2) && $sectionCall) {
00246                                 $result .= 'Type: submenu; ' .
00247                                     'Caption: "' . $key2 . '"; ' .
00248                                     'SubMenu: MenuPhpSetting-' . md5($key2) . '; ' .
00249                                     'Glyph: ' . TplAestan::GLYPH_FOLDER_CLOSE . PHP_EOL;
00250                             } elseif (!is_array($value2)) {
00251                                 $glyph = '';
00252                                 $settingEnabled = $bearsamppBins->getPhp()->isSettingActive($value2);
00253                                 if (!$bearsamppBins->getPhp()->isSettingExists($value2)) {
00254                                     $glyph = TplAestan::GLYPH_WARNING;
00255                                 } elseif ($settingEnabled) {
00256                                     $glyph = TplAestan::GLYPH_CHECK;
00257                                 }
00258                                 $tplSwitchPhpSetting = TplApp::getActionMulti(
00259                                     self::ACTION_SWITCH_SETTING, array($value2, $settingEnabled),
00260                                     array($key2, $glyph),
00261                                     false, get_called_class()
00262                                 );
00263 
00264                                 if ($sectionCall) {
00265                                     $result .= $tplSwitchPhpSetting[TplApp::SECTION_CALL] . PHP_EOL;
00266                                 } else {
00267                                     $result .= $tplSwitchPhpSetting[TplApp::SECTION_CONTENT] . PHP_EOL;
00268                                 }
00269                             }
00270                         }
00271                     } else {
00272                         $result .= self::getSubmenuPhpSettings($passThr, null, $value, $sectionCall);
00273                     }
00274                 }
00275             }
00276         }
00277 
00278         return $result;
00279     }
