00289     public static function getActionSwitchPhpSetting($setting, $enabled)
00290     {
00291         $switch = $enabled ? ActionSwitchPhpParam::SWITCH_OFF : ActionSwitchPhpParam::SWITCH_ON;
00292         return TplApp::getActionRun(Action::SWITCH_PHP_PARAM, array($setting, $switch)) . PHP_EOL .
00293             TplService::getActionRestart(BinApache::SERVICE_NAME) . PHP_EOL .
00294             TplAppReload::getActionReload() . PHP_EOL;
00295     }
